"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["2141"],{8949(e,t,n){n.r(t),n.d(t,{metadata:()=>o,default:()=>u,frontMatter:()=>s,contentTitle:()=>a,toc:()=>l,assets:()=>c});var o=JSON.parse('{"id":"reference/hardware/protocols/mqtt","title":"Introduction to MQTT","description":"av \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/hardware/protocols/mqtt.md","sourceDirName":"reference/hardware/protocols","slug":"/reference/hardware/protocols/mqtt","permalink":"/personal-av-docs/docs/reference/hardware/protocols/mqtt","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/hardware/protocols/mqtt.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Introduction to MQTT","sidebar_label":"Introduction to MQTT","sidebar_position":99,"edition":"av","source":"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt","format":"md"}}'),i=n(4848),r=n(8453);let s={title:"Introduction to MQTT",sidebar_label:"Introduction to MQTT",sidebar_position:99,edition:"av",source:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt",format:"md"},a,c={},l=[];function d(e){let t={a:"a",p:"p",strong:"strong",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[":::note Edition\n",(0,i.jsx)(t.strong,{children:"av"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(t.a,{href:"https://doc.airvantage.net/av/reference/hardware/protocols/mqtt",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(t.p,{children:"Introduction to MQTT\nInitializing Table Of Contents...\nWhat is MQTT?\nMQTT\n(MQ Telemetry Transport) is a publish/subscribe protocol for M2M applications. It\u2019s now an OASIS standard. It\u2019s a simple protocol, easy to implement for any client.\nThis procotol supplies:\nOpen source clients available in multiple languages;\nSmall bandwidth footprint;\nDefine configuration for secure transport through TLS;\nAdd support for registering MQTT-only device on AirVantage;\nWebSocket transport for connecting directly from a web page;\nThe supported version is 3.1.1\nSecurity\nMQTT must be secured using TLS (Transport Layer Security) the successor of SSL. TLS will create a secure tunnel between your client and the server. The server will be authenticated using a X.509 certificate (like for HTTPS websites).\nPublish/Subscribe\nMQTT uses the publish/subscribe paradigm. Clients connect to a \u201Cbroker\u201D, in our case the AirVantage server. Clients can publish messages on \u201Ctopics\u201D. All the subscribers to this topic will receive the messages. A client can connect to any topic. This allows one-to-one, many-to-one or one-to-many communication patterns.\nTopics\nA topic name is an UTF-8 string. It\u2019s used by the broker for matching publisher and subscribers. Topics can be composed using \u201C/\u201D separators.\nA topic doesn\u2019t need to be created upfront, just publish a message on a given topic.\nAirVantage Reserved topics\nAirVantage uses some specific topics to be used if you want to publish data in the AirVantage data store, define alerts, visualize the data or stream it to your servers. Specific topics are also used for receiving operation tasks (like read, write, commands) from AirVantage operations.\nThis is described in the page\nUsing MQTT with AirVantage\n.\nSubscription wildcards\nA client can use wildcards for subscribing to a set of topics. Wildcards are not allowed in publish topics, only for subscribing.\nWildcards are used with topic hierarchy. The topic hierarchy is defined by the \u201C/\u201D used for separating the different sections of a topic.\nThe possible wildcards are:\n\u201D+\u201D for a single level in the topic hierarchy, can be used multiple time in a subscription topic\n\u201D#\u201D for matching multiple levels in the hierarchy, but it needs to be the last character of the topic subscription\nQuality-of-Service (QoS) levels\nYou can send MQTT publish or subscribe messages with a QoS level (0, 1 or 2).\nEach different level provides different guarantees of delivery priority.\nQoS 0: At most one-time delivery. Your data can be lost. No retransmission outside of TCP.\nQoS 1: At least one-time delivery. Your data will be retransmitted if needed. The message can be received more than once.\nQoS 2: Exactly one-time delivery. The message will be delivered exactly once but the communication overhead is high (multiple acknowledgement messages).\nRetained messages\nWhen you publish a message on a topic you can ask the broker to retain the last value for this topic. When a client subscribes to this topic it will receive the last retained value.\nLast will and testament\nWhen a client connects it can ask the broker to publish a specified message on a specified topic if the client disconnects abruptly (without sending the MQTT disconnect message).\nPersistent session\nA client connecting to the broker can specify if it wants a persistent session. This type of session will make the broker keep the undelivered message with QoS 1 or 2.\nSo if the client disconnects, the server will keep the messages and send them at the next reconnection with the same \u201Cclient ID\u201D.\nProtocol Configuration\nPort:\n8883 (SSL/TLS) or 1883 (but without security!)\nurl:\ntcp://eu.airvantage.net\nUsername:\nSerial Number (but IMEI can be used as well)\nPayload Format\nMQTT is payload-agnostic, so you can use any format as payload.\nHowever we have defined a format for you to use with the\nMQTT protocol to connect your embedded application to\nUsing MQTT with AirVantage\n.\nTroubleshooting communications\nUsing MQTT with AirVantage\n: The\nMQTT Errors section\nexplains how to receive trace logs of the data you are sending and how to troubleshoot communications with AirVantage.\nMore on MQTT\nMQTT.org\nEclipse Paho\nMQTT standard at OASIS\nUnderstand the MQTT protocol\nConnect your hardware to AirVantage with MQTT"})]})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>a});var o=n(6540);let i={},r=o.createContext(i);function s(e){let t=o.useContext(r);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function a(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),o.createElement(r.Provider,{value:t},e.children)}}}]);